public void createEmployee(String name, Number deptId, Number salary) {
    if (!isDepartmentValid(deptId)) {
        throw MessageHelper.createRecordNotFoundError("Department", deptId.toString());
    }
    if (salary.doubleValue() < 1000 || salary.doubleValue() > 100000) {
        throw MessageHelper.createInvalidRangeError("Salary", "1000", "100000");
    }
    EmployeeVOImpl vo = getEmployeeVO();
    vo.createEmployee(name, deptId, salary);
    getTransaction().commit();
}

protected void validateEntity() {
    super.validateEntity();
    String empName = (String)getEmployeeName();
    if (empName == null || empName.trim().isEmpty()) {
        throw MessageHelper.createError(MessageConstants.ERR_EMP_NAME_REQUIRED);
    }
    if (empName.length() > 200) {
        throw MessageHelper.createInvalidLengthError("Employee Name", "200");
    }
    Date startDate = (Date)getStartDate();
    Date endDate = (Date)getEndDate();
    if (endDate != null && endDate.before(startDate)) {
        throw MessageHelper.createError(MessageConstants.ERR_DATE_RANGE_INVALID);
    }
}

