protected void validateEntity() {
    super.validateEntity();
    // Get parent via association
    ParentEOImpl parent = (ParentEOImpl)getParent();
    if (parent == null) {
        throw MessageHelper.createFieldRequiredError("Parent");
    }
    // Validate child dates within parent dates
    Date childStart = getStartDate();
    Date parentStart = parent.getStartDate();
    if (childStart.before(parentStart)) {
        throw MessageHelper.createError(
            MessageConstants.ERR_CHILD_START_BEFORE_PARENT
        );
    }
}

