protected void beforeRemove() {
    // Check for child records via association
    RowSet children = (RowSet)getChildren();
    if (children.getEstimatedRowCount() > 0) {
        throw MessageHelper.createDeleteRestrictedError(
            "Parent",
            children.getEstimatedRowCount() + " child records exist"
        );
    }
    super.beforeRemove();
}

